toString() {
    let result = "";
    for (let index = 0; index < this._keys.length; index++) {
        const prop = this._keys[index];
        const value = this[prop];
        const type = typeof value;
        switch (type) {
            case "number":
            case "string":
                result += "#define " + prop + " " + value + "\n";
                break;
            default:
                if (value) {
                    result += "#define " + prop + "\n";
                }
                break;
        }
    }
    return canonicalResult(result);
}
